// Rebind only four nonidentical input boxes to already evaluated real centers.
#define GFS_PENDING29_PROJECTION_LIBRARY
#include "test_shared_pending29_projection_v1.cpp"
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);try{
    need(argc==5&&ranks==1,"control saved previouspacket NEWdest");auto start=std::chrono::steady_clock::now();auto p=curved::read(argv[1]);const auto f=load_saved(std::string(argv[2])+"/shared_state.bin",p);auto before=f.coefficient;std::string previous=argv[3],dest=argv[4];auto events=read29<Event29>(previous+"/actual_reference_events_rank0.bin");auto old=events;auto inverses=read29<aw::InverseFinal>(previous+"/actual_power_inverse_certificates_rank0.bin");auto original=inverses;auto frames=read29<Frame29>(previous+"/oblique_coordinate_frames_rank0.bin");need(events.size()==109&&inverses.size()==8&&frames.size()==14,"same original partial packet");std::map<int,sd::Compiled>maps;uint64_t rebound=0,failed=0;
    std::ofstream rc(dest+"/rebound_input_certificates.csv");rc<<"slot_id,source,target,node,original_inverse_index,new_inverse_index,inside,residual,radius,reason\n";
    for(auto&e:events)if(!e.passed){need(e.kind==2&&std::string(e.reason)=="same event and identical interval input required for reuse","only four explicit reuse failures");auto match=std::find_if(old.begin(),old.end(),[&](const Event29&v){return v.passed&&v.kind==2&&v.source==e.source&&std::string(v.event)==e.event;});need(match!=old.end()&&match->inverse_index<original.size(),"successful same-event real-center certificate");const auto&saved=original[match->inverse_index];if(!maps.count(e.source))maps.emplace(e.source,sd::compile(f,e.source));const auto&m=maps.at(e.source);aw::InverseFinal z=saved;z.slot=e.slot;z.target=e.target;for(int k=0;k<2;k++)z.input[k]=e.input[k];z.residual=std::max(sf::mag(z.position[0]-z.input[0]),sf::mag(z.position[1]-z.input[1]));z.radius=sf::quotient(sf::mul(Q(2),z.residual),mf::FP<Q>::down(Q(1)-z.L));for(int k=0;k<2;k++)z.output[k]=S(z.center[k],z.radius);auto lambda=sf::barycentric(m.base,z.output[0],z.output[1]);z.inside=1;for(int k=0;k<3;k++){z.lambda[k]=lambda[k].v;z.inside=z.inside&&sf::lower(z.lambda[k])>0;e.lambda[k]=z.lambda[k];}e.inverse_index=inverses.size();e.reused=0;for(int k=0;k<2;k++)e.reference[k]=z.output[k];e.passed=z.inside;snprintf(e.reason,sizeof(e.reason),"%s",z.inside?"same_real_center_distinct_input_residual_recertified":"distinct_input_rebinding_strict_source_inclusion_unproved");inverses.push_back(z);rebound+=z.inside;failed+=!z.inside;rc<<e.slot<<','<<e.source<<','<<e.target<<','<<e.node<<','<<match->inverse_index<<','<<e.inverse_index<<','<<z.inside<<','<<qs(z.residual)<<','<<qs(z.radius)<<','<<e.reason<<'\n';}
    rc.close();need(rebound+failed==4,"only four failed records assessed");uint64_t retained=0;for(size_t j=0;j<old.size();j++)if(old[j].passed){need(!memcmp(&events[j],&old[j],sizeof(Event29)),"all105 passing event records byte-exact reuse");retained++;}need(retained==105,"105 previous event proofs reused");std::vector<Projection29>projections;for(const auto&frame:frames){need(frame.passed,"all fourteen original frames preserved");for(const auto&e:events)if(e.slot==frame.slot&&e.passed){Projection29 z={};z.slot=frame.slot;z.chart=frame.chart;z.node=e.node;z.kind=e.kind;for(int k=0;k<2;k++)z.reference[k]=e.reference[k];snprintf(z.event,sizeof(z.event),"%s",e.event);project29(frame,z.reference,z.coordinate);projections.push_back(z);}}
    packet(dest+"/actual_reference_events_rank0.bin",events,0);packet(dest+"/actual_power_inverse_certificates_rank0.bin",inverses,0);packet(dest+"/oblique_coordinate_frames_rank0.bin",frames,0);packet(dest+"/oblique_actual_event_projections_rank0.bin",projections,0);need(!memcmp(before.data(),f.coefficient.data(),before.size()*sizeof(STCoefficient)),"state/heat unchanged");printf("{\"scope\":\"only four differing-input-box reuse rejections; recertify saved same-real-center residuals with original whole-source contraction, preserve105 passing events and14 frames byte-exact\",\"retained_passing_event_records\":105,\"new_distinct_input_residual_certificates\":%llu,\"remaining_failed_event_records\":%llu,\"all29_used_reference_event_packets_complete\":%s,\"retained_oblique_coordinate_frames\":14,\"oblique_event_projections\":%zu,\"new_inverse_Newton_iterations\":0,\"new_field_evaluations\":0,\"new_canonical_root_jobs\":0,\"new_physical_quadrature_queries\":0,\"remaining_incomplete_atlas_slots\":29,\"all_target_actual_atlas_complete\":false,\"full_quadrature_allowed\":false,\"state_unchanged\":true,\"seconds\":%.17g}\n",(unsigned long long)rebound,(unsigned long long)failed,failed?"false":"true",projections.size(),std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count());
}catch(const std::exception&e){fprintf(stderr,"pending29 distinct-input residual rebind FAIL %s\n",e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return 0;}
